mapper.select:
with recursive shared_catalogs as (
    select cast(s.resource_id as signed) as id
    from nip_rt_share s
    where s.resource_type = 'CATALOG'
      and (
        (s.target_type = 'USER' and s.target_user = #{currentUser})

          or (s.target_type = 'ROLE' and s.target_role in

            #{role}
          )

      )
    union
    select c.id
    from nip_rt_catalog c
             inner join shared_catalogs sc on c.father_id = sc.id
)
select  from nip_rt_article a
where a.is_delete = 0 and (a.create_by = #{currentUser}
   or a.is_public = 1
   or exists (
        select 1
        from nip_rt_share s
        where s.resource_type = 'ARTICLE'
          and s.resource_id = a.id
          and (
            (s.target_type = 'USER' and s.target_user = #{currentUser})

              or (s.target_type = 'ROLE' and s.target_role in

                #{role}
              )

          )
    )
   or a.catalog_id in (select id from shared_catalogs))
order by a.update_time desc
limit #{limit}
